import EditServices from "./EditServices"
import EditAbout from "./EditAbout"

import "./index.css"
import ContactForm from "./ContactForm";
import { Stack } from "@mui/material";

const EditText = () => {
    return (
        <Stack>
        <div>
            <EditAbout />
            <EditServices />
        </div>
        <div>
            <ContactForm />
        </div>
        </Stack>
    );
};

export default EditText;
